import json

# Get input details for all 3 problem IDs we need
problem_ids = {'pydata__xarray-6992', 'django__django-14315', 'sphinx-doc__sphinx-11445'}
found = {}

with open('/home/sonny/exec-sim-repair-verifier/data/swebench_full/test.jsonl') as f:
    for line in f:
        rec = json.loads(line)
        pid = rec.get('problem_id')
        if pid in problem_ids and pid not in found:
            found[pid] = {
                'problem_id': pid,
                'mutation_type': rec.get('mutation_type'),
                'test': rec['test'][:200],
                'code_first200': rec['code'][:200],
                'label': rec['label'],
                'execution_output_first200': (rec.get('execution_output') or '')[:200]
            }
            if len(found) == len(problem_ids):
                break

for pid, info in found.items():
    print(json.dumps(info, indent=2))
    print('---')

if len(found) < len(problem_ids):
    missing = problem_ids - set(found.keys())
    print(f'Missing: {missing}')
    # Check traj files
    for fn in ['traj_test.jsonl']:
        with open(f'/home/sonny/exec-sim-repair-verifier/data/swebench_full/{fn}') as f:
            for line in f:
                rec = json.loads(line)
                pid = rec.get('problem_id')
                if pid in missing:
                    print(f'Found {pid} in {fn}, fields: {list(rec.keys())}')
                    print('test:', rec.get('test','')[:200])
                    print('mutation_type:', rec.get('mutation_type'))
"
